Here’s a simple `migrate.js` you can add to your project root that:

- Reads all `.sql` files from `./migrations/`
- Sorts them alphabetically (a common convention)
- Logs each filename in the order it would be applied

```js
// migrate.js
const fs = require('fs');
const path = require('path');

const migrationsDir = path.join(__dirname, 'migrations');

function main() {
  // Check if migrations directory exists
  if (!fs.existsSync(migrationsDir)) {
    console.error(`Migrations directory not found: ${migrationsDir}`);
    process.exit(1);
  }

  // Read all files in the migrations directory
  let files = fs.readdirSync(migrationsDir);

  // Filter for .sql files
  files = files.filter((file) => file.toLowerCase().endsWith('.sql'));

  // Sort files alphabetically (you can change this if you use timestamps, etc.)
  files.sort();

  if (files.length === 0) {
    console.log('No SQL migration files found in ./migrations/');
    return;
  }

  console.log('Migrations that would be applied, in order:');
  for (const file of files) {
    console.log(file);
  }
}

main();
```

