// migrate.js

const fs = require('fs');
const path = require('path');

async function main() {
  const migrationsDir = path.join(__dirname, 'migrations');

  // Check that the directory exists
  if (!fs.existsSync(migrationsDir)) {
    console.error('Migrations directory does not exist:', migrationsDir);
    process.exit(1);
  }

  // Read all .sql files from the migrations directory
  let files;
  try {
    files = fs.readdirSync(migrationsDir)
      .filter(file => file.endsWith('.sql'))
      .sort(); // sort alphabetically; assumes filenames encode order (e.g. 001_, 002_)
  } catch (err) {
    console.error('Error reading migrations directory:', err.message);
    process.exit(1);
  }

  if (files.length === 0) {
    console.log('No migration files found in', migrationsDir);
    return;
  }

  console.log('Migrations that would be applied, in order:');
  for (const file of files) {
    const fullPath = path.join(migrationsDir, file);
    console.log(file); // or console.log(fullPath) if you prefer full paths
  }
}

main().catch(err => {
  console.error('Unexpected error:', err);
  process.exit(1);
});
```

