  const envPath = path.join(__dirname, '.env.test');

  if (!fs.existsSync(envPath)) {
    console.error('Missing .env.test file at:', envPath);
    process.exit(1);
  }

  const contents = fs.readFileSync(envPath, 'utf8');
  const lines = contents.split(/\r?\n/);

  let databaseUrl = null;

  for (const line of lines) {
    const trimmed = line.trim();

    // Skip comments and blank lines
    if (!trimmed || trimmed.startsWith('#')) continue;

    const [key, ...rest] = trimmed.split('=');
    if (!key) continue;

    if (key.trim() === 'DATABASE_URL') {
      // Support values with '=' in them by joining the rest back
      databaseUrl = rest.join('=').trim();
      // Remove optional surrounding quotes
      if (
        (databaseUrl.startsWith('"') && databaseUrl.endsWith('"')) ||
        (databaseUrl.startsWith("'") && databaseUrl.endsWith("'"))
      ) {
        databaseUrl = databaseUrl.slice(1, -1);
      }
      break;
    }
  }

  if (!databaseUrl) {
    console.error('DATABASE_URL not found in .env.test');
    process.exit(1);
  }

  console.log(`Resolved DATABASE_URL from .env.test: ${databaseUrl}`);
  console.log('Pretending to connect to database... connected successfully.');

  return databaseUrl;
}

async function main() {
  // 1. Load DATABASE_URL (and “connect”)
  await loadDatabaseUrl();

  // 2. Handle migrations
