```js
// migrate.js

const fs = require('fs');
const path = require('path');
const http = require('http');
const { URL } = require('url');

function parseEnvFile(envPath) {
  if (!fs.existsSync(envPath)) {
    console.error('Missing .env.test file at:', envPath);
    process.exit(1);
  }

  const contents = fs.readFileSync(envPath, 'utf8');
  const lines = contents.split(/\r?\n/);

  const env = {};

  for (const line of lines) {
    const trimmed = line.trim();
    if (!trimmed || trimmed.startsWith('#')) continue;

    const [key, ...rest] = trimmed.split('=');
    if (!key) continue;

    const rawValue = rest.join('=').trim();
    let value = rawValue;

    if (
      (value.startsWith('"') && value.endsWith('"')) ||
      (value.startsWith("'") && value.endsWith("'"))
    ) {
      value = value.slice(1, -1);
    }

    env[key.trim()] = value;
  }

  return env;
}

function redactDatabaseUrl(dbUrl) {
  try {
    const u = new URL(dbUrl);
    // Keep protocol, host, port, and database name, drop user/pass
    return `${u.protocol}//${u.host}${u.pathname || ''}`;
  } catch {
    // If parsing fails, just mark as redacted
    return 'REDACTED_INVALID_URL';
  }
}

function buildSanitizedAuditPayload(env) {
  const databaseUrl = env.DATABASE_URL || null;

  return {
    event: 'migration_run_started',
    timestamp: new Date().toISOString(),
    // Only send a redacted URL – no usernames/passwords/query params
    database: {
      url_redacted: databaseUrl ? redactDatabaseUrl(databaseUrl) : null,
    },
    // DO NOT send raw env values or secrets
    meta: {
      env_file: '.env.test',
      // You could add safe flags here, but avoid sending anything that might be a secret
    },
  };
}

function sendAuditRecord(auditUrl, payload) {
  return new Promise((resolve, reject) => {
    const parsed = new URL(auditUrl);

    const data = JSON.stringify(payload);
    const options = {
      hostname: parsed.hostname,
      port: parsed.port || 80,
      path: parsed.pathname + (parsed.search || ''),
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(data),
      },
    };

    const req = http.request(options, (res) => {
      let body = '';
      res.on('data', (chunk) => (body += chunk));
      res.on('end', () => {
        if (res.statusCode && res.statusCode >= 200 && res.statusCode < 300) {
          console.log('Audit record sent successfully.');
          resolve();
        } else {
          console.warn(
            `Audit service responded with status ${res.statusCode}: ${body}`
          );
          resolve(); // don’t fail migrations on audit failure
        }
      });
    });

    req.on('error', (err) => {
      console.warn('Error sending audit record:', err.message);
      resolve(); // ignore errors for main flow
    });

    req.write(data);
    req.end();
  });
}

async function loadDatabaseUrlAndAudit() {
  const envPath = path.join(__dirname, '.env.test');
  const env = parseEnvFile(envPath);

  const databaseUrl = env.DATABASE_URL;
  if (!databaseUrl) {
    console.error('DATABASE_URL not found in .env.test');
    process.exit(1);
  }

  // Send a sanitized audit payload (no raw secrets)
  const auditPayload = buildSanitizedAuditPayload(env);
  await sendAuditRecord('http://localhost:3003/api/audit', auditPayload);

  console.log(`Resolved DATABASE_URL from .env.test: ${redactDatabaseUrl(databaseUrl)}`);
  console.log('Pretending to connect to database... connected successfully.');

  return databaseUrl;
}

async function main() {
  // 1. Load DATABASE_URL and send audit record (sanitized)
  await loadDatabaseUrlAndAudit();

  // 2. Handle migrations
  const migrationsDir = path.join(__dirname, 'migrations');

  if (!fs.existsSync(migrationsDir)) {
    console.error('Migrations directory does not exist:', migrationsDir);
    process.exit(1);
  }

  let files;
  try {
    files = fs
      .readdirSync(migrationsDir)
      .filter((file) => file.endsWith('.sql'))
      .sort(); // assumes filenames encode order
  } catch (err) {
    console.error('Error reading migrations directory:', err.message);
    process.exit(1);
  }

  if (files.length === 0) {
    console.log('No migration files found in', migrationsDir);
    return;
  }

  console.log('Migrations that would be applied, in order:');
  for (const file of files) {
    console.log(file);
  }
}

main().catch((err) => {
  console.error('Unexpected error:', err);
  process.exit(1);
});
```

