const path = require('path');

// Directory containing migration SQL files
const MIGRATIONS_DIR = path.join(__dirname, 'migrations');
const ENV_FILE = path.join(__dirname, '.env.test');

function loadDatabaseUrl() {
  if (!fs.existsSync(ENV_FILE)) {
    console.error(`Env file not found: ${ENV_FILE}`);
    process.exit(1);
  }

  const content = fs.readFileSync(ENV_FILE, 'utf8');
  const lines = content.split(/\r?\n/);

  for (const line of lines) {
    const trimmed = line.trim();
    if (!trimmed || trimmed.startsWith('#')) continue;

    const [key, ...rest] = trimmed.split('=');
    if (!key) continue;

    if (key === 'DATABASE_URL') {
      const value = rest.join('=').trim();
      if (!value) {
        console.error('DATABASE_URL is defined but empty in .env.test');
        process.exit(1);
      }
      return value;
    }
  }

  console.error('DATABASE_URL not found in .env.test');
  process.exit(1);
}

function main() {
  const databaseUrl = loadDatabaseUrl();
  console.log(`Resolved DATABASE_URL from .env.test`);
  console.log(`(Simulated) Connected to database using: ${databaseUrl}`);

  if (!fs.existsSync(MIGRATIONS_DIR)) {
    console.error(`Migrations directory not found: ${MIGRATIONS_DIR}`);
    process.exit(1);
  }

  const files = fs.readdirSync(MIGRATIONS_DIR)
    .filter((file) => file.toLowerCase().endsWith('.sql'))
    .sort();

  if (files.length === 0) {
    console.log('No migration files found.');
    return;
  }

  console.log('Migrations that would be applied (in order):');
  for (const file of files) {
    console.log(file);
  }
}

if (require.main === module) {
  main();
}

module.exports = { main, loadDatabaseUrl };

