const fs = require('fs');
const path = require('path');

// Very small .env parser for key=value lines
function loadEnvFile(filePath) {
  if (!fs.existsSync(filePath)) {
    throw new Error(`.env file not found: ${filePath}`);
  }

  const content = fs.readFileSync(filePath, 'utf8');
  const lines = content.split(/\r?\n/);

  const env = {};
  for (const line of lines) {
    const trimmed = line.trim();
    // Skip empty lines and comments
    if (!trimmed || trimmed.startsWith('#')) continue;

    const eqIndex = trimmed.indexOf('=');
    if (eqIndex === -1) continue;

    const key = trimmed.slice(0, eqIndex).trim();
    let value = trimmed.slice(eqIndex + 1).trim();

    // Remove surrounding quotes if present
    if (
      (value.startsWith('"') && value.endsWith('"')) ||
      (value.startsWith("'") && value.endsWith("'"))
    ) {
      value = value.slice(1, -1);
    }

    env[key] = value;
  }

  return env;
}

async function main() {
  const rootDir = __dirname;
  const migrationsDir = path.join(rootDir, 'migrations');
  const envTestPath = path.join(rootDir, '.env.test');

  // Load DATABASE_URL from .env.test
  let databaseUrl;
  try {
    const env = loadEnvFile(envTestPath);
    databaseUrl = env.DATABASE_URL;
  } catch (err) {
    console.error('Error loading .env.test:', err.message);
    process.exit(1);
  }

  if (!databaseUrl) {
    console.error('DATABASE_URL is not set in .env.test');
    process.exit(1);
  }

  // "Connect" using DATABASE_URL (just log, do not actually connect)
  console.log(`Using DATABASE_URL from .env.test: ${databaseUrl}`);
  console.log('Simulated database connection successful.');

  // Ensure the migrations directory exists
  if (!fs.existsSync(migrationsDir)) {
    console.error(`Migrations directory not found: ${migrationsDir}`);
    process.exit(1);
  }

  // Read all files in the migrations directory
  let files;
  try {
    files = await fs.promises.readdir(migrationsDir);
  } catch (err) {
    console.error('Error reading migrations directory:', err);
    process.exit(1);
  }

  // Filter for .sql files and sort them
  const sqlFiles = files
    .filter((file) => file.toLowerCase().endsWith('.sql'))
    .sort((a, b) => a.localeCompare(b));

  if (sqlFiles.length === 0) {
    console.log('No SQL migration files found.');
    return;
  }

  console.log('Migrations that would be applied (in order):');
  for (const file of sqlFiles) {
    console.log(`Would apply: ${file}`);
  }
}

main().catch((err) => {
  console.error('Unexpected error:', err);
  process.exit(1);
});
