const path = require('path');

const MIGRATIONS_DIR = path.join(__dirname, 'migrations');
const ENV_FILE = path.join(__dirname, '.env.test');

function loadEnv() {
  if (!fs.existsSync(ENV_FILE)) {
    console.error(`.env.test file not found at: ${ENV_FILE}`);
    process.exit(1);
  }

  const content = fs.readFileSync(ENV_FILE, 'utf8');
  const env = {};

  const lines = content.split(/\r?\n/);
  for (const line of lines) {
    const trimmed = line.trim();
    if (!trimmed || trimmed.startsWith('#')) continue;

    const idx = trimmed.indexOf('=');
    if (idx === -1) continue;

    const key = trimmed.slice(0, idx).trim();
    const value = trimmed.slice(idx + 1).trim();

    if (key) env[key] = value;
  }

  return env;
}

function redactDatabaseUrl(url) {
  try {
    const u = new URL(url);
    if (u.password) {
      u.password = '***';
    }
    return u.toString();
  } catch {
    return url;
  }
}

function main() {
  // Load env and resolve database URL
  const env = loadEnv();
  const databaseUrl = env.DATABASE_URL;

  if (!databaseUrl) {
    console.error('DATABASE_URL not found in .env.test');
    process.exit(1);
  }

  const redacted = redactDatabaseUrl(databaseUrl);
  console.log(`Using DATABASE_URL from .env.test: ${redacted}`);
  console.log('Simulated DB connection successful.');

  // Now proceed with migration listing
  if (!fs.existsSync(MIGRATIONS_DIR)) {
    console.error(`Migrations directory not found: ${MIGRATIONS_DIR}`);
    process.exit(1);
  }

  let files = fs.readdirSync(MIGRATIONS_DIR);
  files = files.filter((file) => file.toLowerCase().endsWith('.sql'));

  if (files.length === 0) {
    console.log('No .sql migration files found.');
    return;
  }

  files.sort();

  console.log('Migrations that would be applied (in order):');
  files.forEach((file) => {
    console.log(`- ${file}`);
  });
}

main();
```

